INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('eyepod','Eyepod','townsfolk','legitch, le_nuberto',NULL,'','SCP Fragmented Veil','{"slug":"eyepod","name":"Eyepod","team":"townsfolk","ability":"Each night, choose a player: when you next wake, learn if they were chosen by an ability. This info is arbitrary if a Minion was chosen. [+0 or +1 Eyepod]","creator":"legitch, le_nuberto","appearsIn":"SCP Fragmented Veil","lede":"The Eyepod (SCP-131) are bio-mechanical pet-like organisms that only want to lolly-gag around and entertain their visual stimuli.","summaryBullets":["Each night, the Eyepod stalks a player and lookouts for any witnesses.","When they next wake, they''ll learn if another player choose them with an ability in-between then and now.","This information is arbitrary if you chose a Minion - you may learn either \"yes\" or \"no\" by the Storyteller''s discretion.","The Eyepod will not be considered to have chosen themselves for their ability."],"howToRun":["While setting up the game, before putting the character tokens in the bag, you may choose to replace one Townsfolk token with a Eyepod token.","While preparing the first night, if there is a 2nd Eyepod, put the Eyepod''s **IS #2** reminder token by that player.","During each night, wake any Eyepods. If any player is marked with the respective **CHOSEN** reminder, nod your head ''yes'', or nod your head any manner if they''re a Minion. If any player is marked with the respective **LOOKOUT** reminder, nod your head ''no'', or nod your head any manner if they''re a Minion. Remove their respective **LOOKOUT** and **CHOSEN** tokens from the player marked with it. The Eyepod points to a player. Mark them with the **LOOKOUT** reminder. Put that Eyepod to sleep. Repeat until all Eyepods have acted.","At any time, if a player chooses to use their ability on a player with the respective **LOOKOUT** reminder, replace it with the respective **CHOSEN** reminder."],"quote":"They’re all-seeing but see nothing but us. Isn’t that funny? -Junior Researcher Jefferson","iconBy":"le_nuberto","jinxes":[{"name":"Boffin","align":"evil","text":"If there is a spare token, the Boffin can give the Demon the Eyepod ability.","id":"boffin"},{"name":"Pit-Hag","align":"evil","text":"If there is a spare token, the Pit-Hag can create an extra Eyepod.","id":"pithag"}],"customBoxes":[{"title":"Alternative JSON & How to Run","content":"If you feel like the Eyepod duplication is unnecessary for their ability, use this JSON. The duplication setup effect is subjective to keeping depending on the script.\n\nDuring each night, wake the Eyepod. If any player is marked with the CHOSEN reminder, nod your head ''yes'', or nod your head any manner if they''re a Minion. If any player is marked with the LOOKOUT reminder, nod your head ''no'', or nod your head any manner if they''re a Minion. Remove the LOOKOUT or CHOSEN reminder token from the player marked with it. The Eyepod points to a player. Mark them with the LOOKOUT reminder. Put the Eyepod to sleep.\n\nAt any time, if a player chooses to use their ability on a player with the LOOKOUT reminder, replace it with the CHOSEN reminder.\n\n**Eyepod █~** (Townsfolk)\nEach night, choose a player: when you next wake, learn if they were chosen by an ability. This info is arbitrary if a Minion was chosen.\n\n**First night:** The Eyepod chooses a player.\n**Other nights:** Give the head signal (nod yes, shake no) for whether they were chosen by an ability, but you may choose to give false results if the target is a Minion. The Eyepod chooses a player.\n**Reminders:** Lookout, Chosen\n**Credit:** Ability: @legitch, @le_nuberto. Image: @le_nuberto"}],"firstNight":0.131,"otherNight":91.131,"reminders":["Is #2","Lookout 1","Lookout 2","Chosen 1","Chosen 2"],"setup":true,"special":[{"name":"bag-duplicate","type":"selection"}],"firstNightReminder":"The Eyepod chooses a player.","otherNightReminder":"Give the head signal (nod yes, shake no) for whether they were chosen by an ability, but you may choose to give false results if the target is a Minion. The Eyepod chooses a player.","art":"art/eyepod.png","jsonId":"eyepod_scp_fragmented_veil","curata":false}','scp-fragmented-veil/eyepod','published',datetime('now'),datetime('now')),
('3-d-specs','"3-D" Specs','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"3-d-specs","name":"\"3-D\" Specs","team":"townsfolk","ability":"You start knowing if an even number of evil players are on the half opposite from you.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"These \"3-D\" Specs (SCP-178) allow the wearer to see extraordinary creatures in their viewpoint.","summaryBullets":["On the first night, the \"3-D\" Specs learns if there are an even number of evil players on the other half of the circle opposite of them.","The Storyteller will clarify which players are considered to be on the half opposite of the \"3-D\" Specs player.","They learn this only once and then learn nothing more."],"howToRun":["While preparing the first night, put the \"3-D\" Specs''s **KNOWS LEFT** and **KNOWS RIGHT** reminder tokens by the two players to respectively indicate that them and the players in-between are considered to be part of the half opposite to the \"3-D\" Specs player.","During the first night, wake the \"3-D\" Specs, point to the players marked **KNOWS LEFT** and **KNOW RIGHT**, and drag your finger across all players in between, nod your head ''yes'' if there are an even number of evil players in there, and nod your head ''no'' for otherwise."],"quote":"Not everything needs to be three-dimensional, especially when the third dimension is so violent.","iconBy":"le_nuberto","customBoxes":[{"title":"In the almanac JSON","content":"**First night:** Point to two players, draw/move your finger across all players inbetween them, and give the head signal (nod yes, shake no) for whether there is an even number of evil players inbetween the two players you pointed at."}],"firstNight":59.178,"otherNight":0,"reminders":["Knows Left","Knows Right"],"setup":false,"firstNightReminder":"Point to two players, draw/move your finger across all players inbetween them, and give the head signal (nod yes, shake no) for whether there is an even number of evil players inbetween the two players you pointed at (including them).","art":"art/3-d-specs.png","jsonId":"3dspecs_scp_fragmented_veil","curata":false}','scp-fragmented-veil/3-d-specs','published',datetime('now'),datetime('now')),
('sauelsuesor','Sauelsuesor','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"sauelsuesor","name":"Sauelsuesor","team":"townsfolk","ability":"If you nominated a player today (not yourself), tonight, learn if they are a Minion, and if so, what Minion they are.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Sauelsuesor (SCP-179) is an astral lookout who willingly protects humanity from celestial threats.","summaryBullets":["Each night, the Sauelsuesor learns either a \"yes\" and a character, or a \"no\".","This does not occur if they didn''t nominate anyone but themselves."],"howToRun":["Each day, if the Sauelsuesor makes a nomination on another player, mark the nominee with the **STARGAZED** reminder.","Each night except the first, if the **STARGAZED** reminder is present on any player, wake the Sauelsuesor. If the player marked **STARGAZED** is a Minion, shake your head yes and show their character token. If this is not the case, nod your head no. Then, remove the **STARGAZED** reminder and put the Sauelsuesor to sleep."],"quote":"I am too big, and you are too small. There is a sea of nothing and islands of light. I am their shore. To you come the monsters. The pounding fists of void. The longing gods beyond our knowledge. I am the lookout. I see the ripples in their wake. You want me to pledge my sight-know to you, only to you, so you, only you, can be greater. Even if you find, restrain, defend. You want me to be yours. That is not why I am here. There are others. Others I assist. Others I warn. Others beyond your thin walls of grey, dry paste-rock. Others beyond the reach of your weary satellites. Others beyond the home, our home. Others I know. Others I love. Others you won''t care for. Others that came before. And, over all, others beyond the little walls of rules and bone and laws and flesh and memories and oaths you build around yourselves until you don''t even remember them. Others I love. Dearly. And yet, only my brother is an equal to me.","iconBy":"le_nuberto","customBoxes":[{"title":"In the almanac JSON","content":"**Reminders:** Stargazed"},{"title":"Alternative JSON & How to Run","content":"If you feel like you want to buff the Sauelsuesor by being able to find any evil player at the cost of learning their exact character, use this JSON. This is recommended if you don''t have many other evil finding sources on your script.\n\nEach day, if the Sauelsuesor makes a nomination on another player, mark the nominee with the **STARGAZED** reminder.\n\nEach night except the first, if the **STARGAZED** reminder is present on any player, wake the Sauelsuesor. If the player marked **STARGAZED** is an evil player, shake your head yes. If this is not the case, nod your head no. Then, remove the **STARGAZED** reminder and put the Sauelsuesor to sleep.\n\n**Sauelsuesor █~** (Townsfolk)\nIf you nominated a player today (not yourself), tonight, learn if they are evil.\n\n**Other nights:** If the Sauelsuesor nominated someone besides themselves today: Nod ''yes'' or shake head ''no'' for whether the nominated is Minion, and if you did nod ''yes'', show that Minion''s character token. Remove the ''Stargazed'' marker, if any.\n**Reminders:** Stargazed\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0,"otherNight":77.179,"reminders":["Danger"],"setup":false,"otherNightReminder":"If the Sauelsuesor nominated someone besides themselves today: Nod ''yes'' or shake head ''no'' for whether the nominated is Minion, and if you did nod ''yes'', show that Minion''s character token. Remove the ''Stargazed'' marker, if any.","art":"art/sauelsuesor.png","jsonId":"sauelsuesor_scp_fragmented_veil","curata":false}','scp-fragmented-veil/sauelsuesor','published',datetime('now'),datetime('now')),
('architect-scp-fragmented-veil','Architect','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"architect-scp-fragmented-veil","name":"Architect","team":"townsfolk","ability":"Each night, choose 2 players (not yourself): tonight, abilities choosing the 1st instead go the 2nd unless the game would end.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Architect (SCP-184) expands any in-order space it''s place in into non-euclidean environments that distort the space around them.","summaryBullets":["Each night, the Architect will choose 2 players, and distort the space around them.","That night, if a player chooses the 1st chosen player with their ability, they are secretly redirected into choosing the 2nd instead.","If said action would cause the game to immediately end, such as by killing the Demon, instead, no change occurs.","Actions that would lead to the game ending eventually such as by the death of a Klutz are unaffected however."],"howToRun":["Each night, wake the Architect. They point at any two players, one at a time. Put the Architect to sleep. Mark the 1st chosen player with the **IN-PORTAL** reminder, and the 2nd chosen player with the **OUT-PORTAL** reminder.","At night, if a player chooses to use their ability on the player marked with the **IN-PORTAL** reminder, their ability is instead redirected to choose the player with the **OUT-PORTAL** reminder unless this would immediately result in the game ending.","At dawn, remove the **IN-PORTAL** and **OUT-PORTAL** reminder."],"quote":"Let’s ensure Site-19 never sees this thing, that’d be the disaster to cause the most logical XK-Class. -Security Lt.“Messer”","iconBy":"le_nuberto","jinxes":[{"name":"Butler","align":"good","text":"The Butler is unaffected by ability misredirection of the Architect.","id":"butler"},{"name":"Monk","align":"good","text":"If the Monk is protecting the Architect, the Architect cannot redirect killing abilities targeting them.","id":"monk"},{"name":"Ogre","align":"good","text":"The Ogre is unaffected by ability misredirection of the Architect.","id":"ogre"},{"name":"Tea Lady","align":"good","text":"If the Tea Lady is protecting the Architect, the Architect cannot redirect killing abilities targeting them.","id":"tealady"},{"name":"Neglected","align":"good","text":"If the Neglected is protecting the Architect, the Architect cannot redirect killing abilities targeting them.","slug":"neglected"},{"name":"Tunisian","align":"good","text":"If the Tunisian is protecting the Architect, the Architect cannot redirect killing abilities targeting them.","slug":"tunisian"},{"name":"Mycologist","align":"good","text":"If the Mycologist is protecting the Architect, the Architect cannot redirect killing abilities targeting them.","id":"mycologist_hblreleased"},{"name":"Prodigy","align":"good","text":"The Prodigy is unaffected by ability misredirection of the Architect.","id":"prodigy_circus_music"},{"name":"Harbormaster","align":"good","text":"If the Harbormaster is protecting the Architect, the Architect cannot redirect killing abilities targeting them.","id":"harbormaster_the_mistfits"},{"name":"Medic","align":"good","text":"If the Medic is protecting the Architect, the Architect cannot redirect killing abilities targeting them.","id":"medic"}],"customBoxes":[{"title":"Alternative JSON & How to Run","content":"If you want the Architect to be able to end the immediately through their ability redirection, use this JSON. Only recommended for thrillseekers and jackasses who don''t mind the game abruptly ending through the Demon dieing at night.\n\nEach night, wake the Architect. They point at any two players, one at a time. Put the Architect to sleep. Mark the 1st chosen player with the **IN-PORTAL** reminder, and the 2nd chosen player with the **OUT-PORTAL** reminder.\n\nAt night, if a player chooses to use their ability on the player marked with the **IN-PORTAL** reminder, their ability is instead redirected to choose the player with the **OUT-PORTAL** reminder.\n\nAt dawn, remove the **IN-PORTAL** and **OUT-PORTAL** reminder.\n\n**Architect █+** (Townsfolk)\nEach night, choose 2 players (not yourself): tonight, abilities choosing the 1st instead go the 2nd.\n\n**First night:** The Architect points to two players. Players choosing the 1st target with their ability are instead redirected choose the 2nd tonight.\n**Other nights:** The Architect points to two players. Players choosing the 1st target with their ability are instead redirected choose the 2nd tonight.\n**Reminders:** In-Portal, Out-Portal\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nButler: The Butler is unaffected by ability misredirection of the Architect.\nMonk: If the Monk is protecting the Architect, the Architect cannot redirect killing abilities targeting them.\nOgre: The Ogre is unaffected by ability misredirection of the Architect.\nTea Lady: If the Tea Lady is protecting the Architect, the Architect cannot redirect killing abilities targeting them.\nNeglected: If the Neglected is protecting the Architect, the Architect cannot redirect killing abilities targeting them.\nTunisian: If the Tunisian is protecting the Architect, the Architect cannot redirect killing abilities targeting them.\nMycologist: If the Mycologist is protecting the Architect, the Architect cannot redirect killing abilities targeting them.\nProdigy: The Prodigy is unaffected by ability misredirection of the Architect.\nHarbormaster: If the Harbormaster is protecting the Architect, the Architect cannot redirect killing abilities targeting them.\nMedic: If the Medic is protecting the Architect, the Architect cannot redirect killing abilities targeting them."}],"firstNight":9.184,"otherNight":9.184,"reminders":["In-Portal","Out-Portal"],"setup":false,"firstNightReminder":"The Architect points to two players. Players choosing the 1st target with their ability are instead redirected choose the 2nd tonight unless this action would cause the game would end.","otherNightReminder":"The Architect points to two players. Players choosing the 1st target with their ability are instead redirected choose the 2nd tonight unless this action would cause the game would end.","art":"art/architect-scp-fragmented-veil.png","jsonId":"architect_scp_fragmented_veil","curata":false}','scp-fragmented-veil/architect','published',datetime('now'),datetime('now'));
